import { spawn } from 'node:child_process';
const chrome = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const file = 'file://' + process.argv[2];
const p = spawn(chrome, ['--headless=new', '--remote-debugging-port=9333', '--user-data-dir=/tmp/kcheck/prof', '--no-first-run', 'about:blank'], { stdio: 'ignore' });
await new Promise(r => setTimeout(r, 1500));
const targets = await (await fetch('http://127.0.0.1:9333/json')).json();
const ws = new WebSocket(targets.find(t => t.type === 'page').webSocketDebuggerUrl);
await new Promise(r => ws.onopen = r);
let id = 0; const pend = {}; const logs = [];
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (d.id && pend[d.id]) { pend[d.id](d); delete pend[d.id]; } if (d.method === 'Runtime.consoleAPICalled') logs.push(d.params.type + ': ' + d.params.args.map(a => a.value ?? a.description).join(' ')); if (d.method === 'Runtime.exceptionThrown') logs.push('EXC ' + JSON.stringify(d.params.exceptionDetails.exception?.description || d.params.exceptionDetails.text)); };
const send = (method, params = {}) => new Promise(r => { const i = ++id; pend[i] = r; ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })).result.result.value;
await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: file });
await new Promise(r => setTimeout(r, 2500));
const out = {};
// hover Oct band
out.hover = await ev(`(()=>{const h=[...document.querySelectorAll('#rev-chart .hit')][11];const r=h.getBoundingClientRect();return [r.x+r.width/2,r.y+r.height/2]})()`);
await send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: out.hover[0], y: out.hover[1] });
await new Promise(r => setTimeout(r, 300));
out.tip = await ev(`document.querySelector('#rev-tip').innerText + ' | on=' + document.querySelector('#rev-tip').classList.contains('on')`);
await send('Page.captureScreenshot', { format: 'png' }).then(r => import('node:fs').then(fs => fs.writeFileSync('/tmp/kcheck/hover.png', Buffer.from(r.result.data, 'base64'))));
await ev(`document.querySelector('[data-channel=online]').click()`);
await new Promise(r => setTimeout(r, 200));
out.online = await ev(`[...document.querySelectorAll('#rev-chart svg text')].map(t=>t.textContent).join(',')`);
await ev(`document.querySelector('[data-channel=cafes]').click()`);
out.cafes = await ev(`[...document.querySelectorAll('#rev-chart svg text')].map(t=>t.textContent).slice(0,6).join(',')`);
await ev(`document.querySelector('#cafes th[data-key=change] .sort').click()`);
out.sortChange = await ev(`[...document.querySelectorAll('#cafes tbody tr')].map(r=>r.dataset.name).join(',')`);
await ev(`document.querySelector('#cafes th[data-key=name] .sort').click()`);
out.sortName = await ev(`[...document.querySelectorAll('#cafes tbody tr')].map(r=>r.dataset.name).join(',') + ' ' + document.querySelector('#cafes th[data-key=name]').getAttribute('aria-sort')`);
await ev(`(()=>{const s=document.querySelector('#search');s.value='ruiz';s.dispatchEvent(new Event('input'))})()`);
out.search = await ev(`[...document.querySelectorAll('#orders-table tbody tr')].filter(r=>!r.hidden).map(r=>r.innerText.replace(/\\s+/g,' ')).join(' / ')`);
await ev(`(()=>{const s=document.querySelector('#search');s.value='zzz';s.dispatchEvent(new Event('input'))})()`);
out.searchNone = await ev(`[...document.querySelectorAll('tr.empty-row')].map(r=>r.hidden+':'+r.innerText).join(' / ')`);
await ev(`(()=>{const s=document.querySelector('#search');s.value='';s.dispatchEvent(new Event('input'))})()`);
// phone
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await new Promise(r => setTimeout(r, 400));
